const webhook = $('INT | Authenticated Deal Ingestion').item.json;
const governance = $json ?? {};
const body = webhook.body && typeof webhook.body === 'object' && !Array.isArray(webhook.body)
  ? webhook.body
  : webhook;

const errors = [];
const now = new Date();
const suffix = Math.random().toString(36).slice(2, 10).toUpperCase();
const requestId = `INGEST-${now.getTime()}-${suffix}`;
const correlationId = `CORR-${now.getTime()}-${suffix}`;

if (governance.connector_key !== 'rest_ingestion_api' ||
    governance.connector_active !== true ||
    Number(governance.contract_version) !== 1) {
  errors.push({code:'CONNECTOR_NOT_READY', field:'connector', message:'REST ingestion connector is not active on contract version 1'});
}

const sourceRecordId = typeof body.source_record_id === 'string' ? body.source_record_id.trim() : '';
if (!sourceRecordId || sourceRecordId.length > 200) {
  errors.push({code:'SOURCE_RECORD_ID_INVALID', field:'source_record_id', message:'source_record_id is required and must be at most 200 characters'});
}

const amount = Number(body.amount);
if (!Number.isFinite(amount) || amount < 0 || amount > 9999999999999999.99) {
  errors.push({code:'AMOUNT_INVALID', field:'amount', message:'amount must be a non-negative number within the canonical numeric range'});
}
const currency = typeof body.currency_code === 'string' ? body.currency_code.trim().toUpperCase() : '';
const expectedCurrency = typeof governance.currency_code === 'string' ? governance.currency_code.trim().toUpperCase() : '';
if (!/^[A-Z]{3}$/.test(currency) || !expectedCurrency || currency !== expectedCurrency) {
  errors.push({code:'CURRENCY_INVALID', field:'currency_code', message:'currency_code must match the configured business currency'});
}

const stageName = typeof body.stage_name === 'string' ? body.stage_name.trim() : '';
if (!stageName || stageName.length > 200) {
  errors.push({code:'STAGE_NAME_INVALID', field:'stage_name', message:'stage_name is required and must be at most 200 characters'});
}

const stageCategory = typeof body.stage_category === 'string' ? body.stage_category.trim().toLowerCase() : '';
if (!['open','won','lost'].includes(stageCategory)) {
  errors.push({code:'STAGE_CATEGORY_INVALID', field:'stage_category', message:'stage_category must be open, won, or lost'});
}

function normalizeTimestamp(field, required = false) {
  const raw = body[field];
  if (raw === undefined || raw === null || raw === '') {
    if (required) errors.push({code:'TIMESTAMP_REQUIRED', field, message:`${field} is required for closed deals`});
    return null;
  }
  const parsed = new Date(raw);
  if (Number.isNaN(parsed.getTime())) {
    errors.push({code:'TIMESTAMP_INVALID', field, message:`${field} must be a valid ISO-compatible timestamp`});
    return null;
  }
  return parsed.toISOString();
}
const createdAt = normalizeTimestamp('created_at');
const expectedCloseDate = normalizeTimestamp('expected_close_date');
const closedAt = normalizeTimestamp('closed_at', ['won','lost'].includes(stageCategory));
const sourceUpdatedAt = normalizeTimestamp('source_updated_at');

const normalizedPayload = {
  ...body,
  amount,
  currency_code: currency,
  stage_name: stageName,
  stage_category: stageCategory,
  created_at: createdAt,
  expected_close_date: expectedCloseDate,
  closed_at: stageCategory === 'open' ? null : closedAt,
  source_updated_at: sourceUpdatedAt
};

if (JSON.stringify(normalizedPayload).length > 65536) {
  errors.push({code:'PAYLOAD_TOO_LARGE', field:'body', message:'JSON payload must not exceed 64 KiB after normalization'});
}

return {
  connector_key: 'rest_ingestion_api',
  request_id: requestId,
  correlation_id: correlationId,
  source_record_id: sourceRecordId,
  source_payload: normalizedPayload,
  validation: {is_valid: errors.length === 0, errors, validated_at: now.toISOString()},
  workflow_stage: errors.length === 0 ? 'rest_payload_validated' : 'rest_payload_rejected'
};

const ctx = $('VAL | Normalize REST Deal').item.json;
const deal = $('DB | Verify Canonical Deal').item.json;
const ingest = $('DB | Ingest Canonical Deal').item.json;

return {
  status: 'success',
  http_status: 200,
  request_id: ctx.request_id,
  correlation_id: ctx.correlation_id,
  connector_key: ctx.connector_key,
  source_record_id: ctx.source_record_id,
  ingestion_status: ingest.ingestion_status ?? 'upserted',
  canonical_deal: {
    deal_id: deal.deal_id,
    deal_name: deal.deal_name,
    amount: deal.amount,
    currency_code: deal.currency_code,
    stage_name: deal.stage_name,
    stage_category: deal.stage_category,
    sales_rep: deal.sales_rep,
    lead_source: deal.lead_source,
    created_at: deal.created_at,
    expected_close_date: deal.expected_close_date,
    closed_at: deal.closed_at,
    source_updated_at: deal.source_updated_at
  }
};

return {
  status: 'rejected',
  http_status: 400,
  request_id: $json.request_id,
  correlation_id: $json.correlation_id,
  connector_key: $json.connector_key,
  source_record_id: $json.source_record_id || null,
  errors: $json.validation?.errors ?? [{code:'VALIDATION_FAILED', message:'Request validation failed'}]
};
